INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7275918, 1133137, 15029, '<td valign="top">Woah! The composition here is incredibly bold, I like it a lot.<br/> <br/>My favorite image so far for this challenge!</td>', 'Woah! The composition here is incredibly bold, I like it a lot. My favorite image so far for this challenge!', '2014-10-22 01:32:57.000000', NULL, 1),
(7275923, 1133022, 15029, '<td valign="top">Fun subject, image is nice and sharp. It feels a bit over-saturated on the blue level. re-composing the image to move the subject off-center (rule of thirds) might make the image a bit more dynamic.</td>', 'Fun subject, image is nice and sharp. It feels a bit over-saturated on the blue level. re-composing the image to move the subject off-center (rule of thirds) might make the image a bit more dynamic.', '2014-10-22 01:39:07.000000', NULL, 1),
(7275925, 1133047, 15029, '<td valign="top">Great, fun image. I get it, but the link to the challenge is a bit tenuous.</td>', 'Great, fun image. I get it, but the link to the challenge is a bit tenuous.', '2014-10-22 01:40:47.000000', NULL, 1),
(7275930, 1132768, 15029, '<td valign="top">Great use of HDR!</td>', 'Great use of HDR!', '2014-10-22 01:42:59.000000', NULL, 1),
(7275948, 1133119, 6519, '<td valign="top">I didn''t enter, but my very first idea was the shocking mess my husband leaves in the kitchen when he does cook. So this is MY pick of the bunch. I like it because I can relate to it so well  :-)</td>', 'I didn''t enter, but my very first idea was the shocking mess my husband leaves in the kitchen when he does cook. So this is MY pick of the bunch. I like it because I can relate to it so well  :-)', '2014-10-22 03:08:19.000000', NULL, 1),
(7275949, 1133077, 6519, '<td valign="top">The lovely quality aside (the crisp foreground, the nice blur and lovely colours in the background, the composition..), I quite like the way it leaves me guessing. It doesn''t look like anything is actually going on (i.e. you just held up that tape for a moment), but then again, I could be wrong..... Nice shot.</td>', 'The lovely quality aside (the crisp foreground, the nice blur and lovely colours in the background, the composition..), I quite like the way it leaves me guessing. It doesn''t look like anything is actually going on (i.e. you just held up that tape for a moment), but then again, I could be wrong..... Nice shot.', '2014-10-22 03:10:22.000000', NULL, 1),
(7275950, 1133083, 6519, '<td valign="top">Yikes... could you be any more ON challenge? Nice catch, nice pic !!!!</td>', 'Yikes... could you be any more ON challenge? Nice catch, nice pic !!!!', '2014-10-22 03:10:55.000000', NULL, 1),
(7275951, 1133102, 6519, '<td valign="top">Ever so simple, yet ever so effective. It didn''t even need the extra explanation in the title.</td>', 'Ever so simple, yet ever so effective. It didn''t even need the extra explanation in the title.', '2014-10-22 03:11:41.000000', NULL, 1),
(7275952, 1133037, 6519, '<td valign="top">Awesome!!! It tells a fabulous story, has just the right DOF and composition.. I like it a lot.</td>', 'Awesome!!! It tells a fabulous story, has just the right DOF and composition.. I like it a lot.', '2014-10-22 03:12:27.000000', NULL, 1),
(7275953, 1133101, 6519, '<td valign="top">I love the concept, the faces, the expressions, the whole idea. The only thing I find odd is the  strong light coming from the patient/experiment and therefore the shadows on the ceiling.... somehow that part doesn''t make sense to me. Still a 9, though.</td>', 'I love the concept, the faces, the expressions, the whole idea. The only thing I find odd is the  strong light coming from the patient/experiment and therefore the shadows on the ceiling.... somehow that part doesn''t make sense to me. Still a 9, though.', '2014-10-22 03:14:15.000000', NULL, 1),
(7275954, 1133072, 6519, '<td valign="top">Your picture says it all... the whole, sad story. The vignette works well for me, too. Good job.</td>', 'Your picture says it all... the whole, sad story. The vignette works well for me, too. Good job.', '2014-10-22 03:15:05.000000', NULL, 1),
(7275955, 1133049, 6519, '<td valign="top">I am loving the angle of the light, and the way this is making me guess the story. Great job.</td>', 'I am loving the angle of the light, and the way this is making me guess the story. Great job.', '2014-10-22 03:15:36.000000', NULL, 1),
(7275956, 1133051, 6519, '<td valign="top">I don''t get this one, I''m just not sure what I am looking at. Now don''t simply think I am an idiot - even if I AM missing something, I still think it is YOUR job to get your point across. I have spent ages staring at this, and I do have some ideas, but I still can''t be sure. So after all this effort on my behalf, I wonder if perhaps YOU could have found a different way to show this to us/me.  A slightly different angle would no doubt give a VERY different result.<br/> <br/>On the other hand, if I am the ONLY one with this problem, just ignore me and be happy everyone else got it perfectly :-)</td>', 'I don''t get this one, I''m just not sure what I am looking at. Now don''t simply think I am an idiot - even if I AM missing something, I still think it is YOUR job to get your point across. I have spent ages staring at this, and I do have some ideas, but I still can''t be sure. So after all this effort on my behalf, I wonder if perhaps YOU could have found a different way to show this to us/me.  A slightly different angle would no doubt give a VERY different result. On the other hand, if I am the ONLY one with this problem, just ignore me and be happy everyone else got it perfectly :-)', '2014-10-22 03:21:22.000000', NULL, 1),
(7275957, 1133041, 6519, '<td valign="top">I am sorry, but this just doesn''t make my socks go up and down. I have taken countless photos that I thought were a good idea at the time, but once I studied them on the computer, I wasn''t sure anymore. Once I tried to put myself into someone else''s shoes (i.e. someone with NO connection to my photo), I didn''t bother to take it any further.<br/> <br/>I think this is one of those cases. It makes sense to YOU because you have a connection to it.... we don''t. 5</td>', 'I am sorry, but this just doesn''t make my socks go up and down. I have taken countless photos that I thought were a good idea at the time, but once I studied them on the computer, I wasn''t sure anymore. Once I tried to put myself into someone else''s shoes (i.e. someone with NO connection to my photo), I didn''t bother to take it any further. I think this is one of those cases. It makes sense to YOU because you have a connection to it.... we don''t. 5', '2014-10-22 03:25:36.000000', NULL, 1),
(7275959, 1132867, 6519, '<td valign="top">I see a sunset, but with no feeling of "aftermath".<br/> <br/>I don''t care for the "dust bunny" up the top and I am rarely a fan of a VERY centered composition (both horizon and subject). The foreground holds limited interest, although it is pretty the way the sun is putting a glow on the very tips of some plants.</td>', 'I see a sunset, but with no feeling of "aftermath". I don''t care for the "dust bunny" up the top and I am rarely a fan of a VERY centered composition (both horizon and subject). The foreground holds limited interest, although it is pretty the way the sun is putting a glow on the very tips of some plants.', '2014-10-22 03:27:56.000000', NULL, 1),
(7275960, 1132877, 6519, '<td valign="top">I don''t understand the connection with "aftermath" when I look at a little kid playing with some coloured lights.</td>', 'I don''t understand the connection with "aftermath" when I look at a little kid playing with some coloured lights.', '2014-10-22 03:29:04.000000', NULL, 1),
(7275962, 1133126, 6519, '<td valign="top">I nearly always detest crazy angles, but since this might possibly suggest the aftermath of a storm, perhaps it is suitable.<br/>However, I certainly don''t like the bad quality of the image.... I do believe that even most camera phones can do better than that these days, plus there are ways of dealing with digital noise.<br/> <br/>If you MEANT for all that grain/noise etc to be there, then I''m sorry.... it just doesn''t do it for me.</td>', 'I nearly always detest crazy angles, but since this might possibly suggest the aftermath of a storm, perhaps it is suitable.However, I certainly don''t like the bad quality of the image.... I do believe that even most camera phones can do better than that these days, plus there are ways of dealing with digital noise. If you MEANT for all that grain/noise etc to be there, then I''m sorry.... it just doesn''t do it for me.', '2014-10-22 03:31:13.000000', NULL, 1),
(7275963, 1133040, 6519, '<td valign="top">The office is "burning".... I am trying very hard to not say "shoehorn", but I can''t really come up with any other explanation.<br/> <br/>Very pretty colour combination, though.... Satan must be in there somewhere, I''m sure  :-)</td>', 'The office is "burning".... I am trying very hard to not say "shoehorn", but I can''t really come up with any other explanation. Very pretty colour combination, though.... Satan must be in there somewhere, I''m sure  :-)', '2014-10-22 03:32:49.000000', NULL, 1),
(7275964, 1133039, 6519, '<td valign="top">I am liking the colours, the composition, and the crisp, clear silhouettes. <br/> <br/>Was that a lucky find, or did you set it up somehow? Not sure what it might be an "aftermath" OF, but I believe it  :-)</td>', 'I am liking the colours, the composition, and the crisp, clear silhouettes.  Was that a lucky find, or did you set it up somehow? Not sure what it might be an "aftermath" OF, but I believe it  :-)', '2014-10-22 03:34:35.000000', NULL, 1),
