(7276077, 1133066, 163081, '<td valign="top">Nice shot. Love the bird tag still visible. If the picture was taken from a lower position you could create more depth. A 7 from</td>', 'Nice shot. Love the bird tag still visible. If the picture was taken from a lower position you could create more depth. A 7 from', '2014-10-22 10:55:13.000000', NULL, 1),
